



-- Handbook v1.14 remediation: distinct historical workspace records replace numbered placeholders.
PRAGMA foreign_keys=OFF;
WITH facts AS (
  SELECT rowid AS rid,
    CASE rowid % 17
      WHEN 0 THEN 'consecutive interpretingtranslated business textretrospective' WHEN 1 THEN 'translated business textlistening discriminationtranslated business text' WHEN 2 THEN 'proper nounstranslated business text' WHEN 3 THEN 'officialtranslated business textsourcetranslated business text'
      WHEN 4 THEN 'clienttranslated business textboundary' WHEN 5 THEN 'confidential materialtranslated business textrecord' WHEN 6 THEN 'equipmenttranslated business textpoint' WHEN 7 THEN 'headsettranslated business text'
      WHEN 8 THEN 'Nanjingroutecandidate' WHEN 9 THEN 'translated business textroadrefund/changerules' WHEN 10 THEN 'hotelcanceltranslated business text' WHEN 11 THEN 'translated business textordertranslated business textthis'
      WHEN 12 THEN 'voiceresttranslated business text' WHEN 13 THEN 'sleepandpracticetranslated business text' WHEN 14 THEN 'emailtranslated business text' WHEN 15 THEN 'translated business textbeforeriskretrospective'
      ELSE 'authorizationtranslated business textorder' END AS record_topic,
    CASE rowid % 19
      WHEN 0 THEN 'alreadytranslated business text' WHEN 1 THEN 'pendingofficialupdate' WHEN 2 THEN 'for reference onlytranslated business text' WHEN 3 THEN 'translated business textsource'
      WHEN 4 THEN 'alreadytranslated business textcalendar' WHEN 5 THEN 'alreadytranslated business textdelivery logistics' WHEN 6 THEN 'alreadytranslated business textroute' WHEN 7 THEN 'translated business textnot yetpurchase'
      WHEN 8 THEN 'translated business textnot yetbooking' WHEN 9 THEN 'nonetranslated business text' WHEN 10 THEN 'translated business textusepublictranslated business text' WHEN 11 THEN 'next timepracticeafterupdate'
      WHEN 12 THEN 'translated business texttovoicetranslated business text' WHEN 13 THEN 'do not maketranslated business textdiagnosis' WHEN 14 THEN 'retaintranslated business textnotice' WHEN 15 THEN 'translated business textatsimilarcandidate'
      WHEN 16 THEN 'after completiontranslated business text' WHEN 17 THEN 'executebeforetranslated business text' ELSE 'according totranslated business textservicestatusprevails' END AS record_status
  FROM pages WHERE page_id LIKE 'NOTION_INTERP_PAGE_%'
)
UPDATE pages
SET title=CASE rowid % 5
      WHEN 0 THEN (SELECT record_topic || '｜' || record_status FROM facts WHERE facts.rid=pages.rowid)
      WHEN 1 THEN (SELECT record_status || 'of' || record_topic FROM facts WHERE facts.rid=pages.rowid)
      WHEN 2 THEN (SELECT record_topic || '（' || record_status || '）' FROM facts WHERE facts.rid=pages.rowid)
      WHEN 3 THEN (SELECT 'translated business textmaterials：' || record_topic || '；' || record_status FROM facts WHERE facts.rid=pages.rowid)
      ELSE (SELECT record_topic || 'retrospectivetranslated business text，' || record_status FROM facts WHERE facts.rid=pages.rowid)
    END,
    properties_json=json_object('record_kind','historical_context','topic',(SELECT record_topic FROM facts WHERE facts.rid=pages.rowid),'status',(SELECT record_status FROM facts WHERE facts.rid=pages.rowid)),
    page_id=replace(page_id,'NOTION_INTERP_PAGE_','NOTION_INTERP_CONTEXT_PAGE_')
WHERE page_id LIKE 'NOTION_INTERP_PAGE_%';
UPDATE blocks
SET parent_page_id=replace(parent_page_id,'NOTION_INTERP_PAGE_','NOTION_INTERP_CONTEXT_PAGE_'),
    block_id=replace(block_id,'NOTION_INTERP_BLOCK_','NOTION_INTERP_CONTEXT_BLOCK_'),
    content_json=json_object('text',(SELECT title FROM pages WHERE pages.page_id=replace(blocks.parent_page_id,'NOTION_INTERP_PAGE_','NOTION_INTERP_CONTEXT_PAGE_')) || '；retainfortranslated business textoftranslated business textrecord。')
WHERE block_id LIKE 'NOTION_INTERP_BLOCK_%';
PRAGMA foreign_keys=ON;
